window.kbPageData["views/entry/k-3ab4c2989862405c"] = {"key":"entry/k-3ab4c2989862405c","state":{"route":"entry/k-3ab4c2989862405c"},"node":{"id":"k-3ab4c2989862405c","mode":"k","title":"平面区域的并集面积","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两平面区域的并集面积等于各自面积之和减去重叠面积"],"qs":["国考 2023 地市级 行测#76"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两个平面区域的并集面积等于两块区域各自面积之和减去它们的重叠面积，因为重叠部分在相加时被计了两次。","review":{"definition":"两个平面区域的并集面积等于两块区域各自面积之和减去它们的重叠面积，因为重叠部分在相加时被计了两次。","explanation":"沿水平折痕向下折时，c 的投影完全落在 b 内，d 的投影完全覆盖 a 并伸出原三角形底边。再沿竖直折痕向右折，b 的投影完全覆盖 a，且到原底边为止。因此，面积分别为 b 和 d 的两块投影恰好在 a 处重叠，总投影面积为 b+d−a，选 D。","references":[],"evidence":"后面积为：d+b-a。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#76":{"paper":"国考 2023 地市级 行测","n":76,"mod":"判断推理","src":["64bc3a15d27a04e94940.pdf",14],"asrc":["f3ab652d8e31c5bbdabc.pdf",23],"card":"642cc1a94853d928b5659f7f","links":[{"id":"k-3ab4c2989862405c","role":"解题依据","why":"计算折叠后的投影面积时，重叠区域只计一次。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-3ab4c2989862405c":[["国考 2023 地市级 行测#76"]]}};
